async function saveRendered(file,buffer){
 try{if(fs.readFileSync(file).equals(buffer))return;}catch{}
 const temporary=file+'.rendering';fs.writeFileSync(temporary,buffer);
 for(let n=0;n<5;n++){try{fs.renameSync(temporary,file);return;}catch(e){if(n===4)throw e;await new Promise(r=>setTimeout(r,250));}}
}
